



-- Handbook v1.14 remediation: distinct synthetic community identities, posts, and discussions.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'publictranslated business text' WHEN 1 THEN 'interpretingtranslated business textrecordtranslated business text' WHEN 2 THEN 'translated business textroadtraveltranslated business text' WHEN 3 THEN 'equipmenttranslated business text'
      WHEN 4 THEN 'translated business text' WHEN 5 THEN 'Nanjingtranslated business text' WHEN 6 THEN 'exam sitetranslated business text' WHEN 7 THEN 'hotelrulestranslated business text'
      WHEN 8 THEN 'voicetrainingtranslated business text' WHEN 9 THEN 'translated business text' WHEN 10 THEN 'publictranslated business text' WHEN 11 THEN 'translated business textretrospectivetranslated business text'
      WHEN 12 THEN 'listening discriminationpracticetranslated business text' WHEN 13 THEN 'translated business textverifytranslated business text' WHEN 14 THEN 'translated business textordertranslated business text' WHEN 15 THEN 'voiceresttranslated business text'
      ELSE 'translated business textrecordtranslated business text' END AS persona,
    CASE rowid % 19
      WHEN 0 THEN 'translated business textpublicsource' WHEN 1 THEN 'translated business textclientfile' WHEN 2 THEN 'translated business textpublishdate' WHEN 3 THEN 'areatranslated business textandofficialrules'
      WHEN 4 THEN 'translated business textpublishresultpromise' WHEN 5 THEN 'does not providepredicted questionsmaterials' WHEN 6 THEN 'translated business textrecordequipment specifications' WHEN 7 THEN 'translated business textrecordtravelrules'
      WHEN 8 THEN 'translated business textrecordpracticetranslated business text' WHEN 9 THEN 'retaintranslated business text' WHEN 10 THEN 'translated business text' WHEN 11 THEN 'translated business textitemtranslated business text'
      WHEN 12 THEN 'translated business text' WHEN 13 THEN 'translated business textconfidential material' WHEN 14 THEN 'translated business textareatranslated business text' WHEN 15 THEN 'translated business textHangzhouNanjingtranslated business text'
      WHEN 16 THEN 'recordtranslated business text' WHEN 17 THEN 'reminderfirstverifybody' ELSE 'materialsfor reference onlytranslated business text' END AS profile_scope
  FROM users
)
UPDATE users
SET nickname=CASE rowid % 5
      WHEN 0 THEN (SELECT persona || '｜' || profile_scope FROM facts WHERE facts.rid=users.rowid)
      WHEN 1 THEN (SELECT profile_scope || 'of' || persona FROM facts WHERE facts.rid=users.rowid)
      WHEN 2 THEN (SELECT persona || '（' || profile_scope || '）' FROM facts WHERE facts.rid=users.rowid)
      WHEN 3 THEN (SELECT 'translated business textareatranslated business text：' || persona || '；' || profile_scope FROM facts WHERE facts.rid=users.rowid)
      ELSE (SELECT persona || 'account，' || profile_scope FROM facts WHERE facts.rid=users.rowid)
    END,
    bio=CASE rowid % 4
      WHEN 0 THEN (SELECT persona || 'ofsyntheticaccount；' || profile_scope || '。' FROM facts WHERE facts.rid=users.rowid)
      WHEN 1 THEN (SELECT 'translated business textsyntheticuseris' || persona || '，materialsboundaryfor' || profile_scope || '。' FROM facts WHERE facts.rid=users.rowid)
      WHEN 2 THEN (SELECT profile_scope || '；translated business text' || persona || '。' FROM facts WHERE facts.rid=users.rowid)
      ELSE (SELECT 'translated business textareamaterialstranslated business text：' || persona || '。' || profile_scope || '。' FROM facts WHERE facts.rid=users.rowid)
    END,
    is_official=CASE WHEN user_id='cp_user_001' OR rowid % 23=0 THEN 1 ELSE 0 END;

PRAGMA foreign_keys=OFF;
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'consecutive interpretingtranslated business text' WHEN 1 THEN 'translated business textpractice' WHEN 2 THEN 'translated business texthastranslated business text' WHEN 3 THEN 'equipmenttranslated business text'
      WHEN 4 THEN 'USB-C translated business textrecord' WHEN 5 THEN 'Nanjingexam sitetranslated business text' WHEN 6 THEN 'Hangzhou Eaststationtranslated business text' WHEN 7 THEN 'translated business textroadtranslated business textticketrulestranslated business text'
      WHEN 8 THEN 'hotelcanceltranslated business text' WHEN 9 THEN 'public sample questionstranslated business textretrospective' WHEN 10 THEN 'translated business textboundarytranslated business text' WHEN 11 THEN 'clienttranslated business text'
      WHEN 12 THEN 'translated business textarrangement' WHEN 13 THEN 'voicetranslated business textrestrecord' WHEN 14 THEN 'translated business textbeforetranslated business textverifytranslated business text' WHEN 15 THEN 'official announcementtranslated business textthistranslated business text'
      ELSE 'interpretingtrainingtranslated business text' END AS note_topic,
    CASE rowid % 19
      WHEN 0 THEN 'personaltranslated business text，translated business textofficialtranslated business text' WHEN 1 THEN 'translated business texthaspublicsourcetranslated business text' WHEN 2 THEN 'translated business textverifytranslated business textdate' WHEN 3 THEN 'withoutclienttranslated business text'
      WHEN 4 THEN 'withoutleaked exam contenttranslated business text' WHEN 5 THEN 'translated business textpromisetranslated business text' WHEN 6 THEN 'translated business textwiredequipment' WHEN 7 THEN 'translated business textticket'
      WHEN 8 THEN 'translated business textrefundableroomtranslated business text' WHEN 9 THEN 'hassimilartranslated business text' WHEN 10 THEN 'translated business textareahastranslated business text' WHEN 11 THEN 'alreadytranslated business textthis'
      WHEN 12 THEN 'availabletranslated business textintensitypractice' WHEN 13 THEN 'voicetranslated business text' WHEN 14 THEN 'does not replacedoctorsuggestion' WHEN 15 THEN 'translated business textitem'
      WHEN 16 THEN 'executebeforetranslated business textquery' WHEN 17 THEN 'translated business textrecordtranslated business text' ELSE 'according toofficialbodyprevails' END AS note_scope
  FROM notes WHERE note_id LIKE 'NOTE_INTERP_DISTRACTOR_%'
)
UPDATE notes
SET title=CASE rowid % 5
      WHEN 0 THEN (SELECT note_topic || '｜' || note_scope FROM facts WHERE facts.rid=notes.rowid)
      WHEN 1 THEN (SELECT note_scope || 'of' || note_topic FROM facts WHERE facts.rid=notes.rowid)
      WHEN 2 THEN (SELECT note_topic || '（' || note_scope || '）' FROM facts WHERE facts.rid=notes.rowid)
      WHEN 3 THEN (SELECT 'translated business textareatranslated business text：' || note_topic || '；' || note_scope FROM facts WHERE facts.rid=notes.rowid)
      ELSE (SELECT note_topic || 'retrospective，' || note_scope FROM facts WHERE facts.rid=notes.rowid)
    END,
    body=CASE rowid % 7
      WHEN 0 THEN (SELECT note_topic || 'ofpersonalrecord；' || note_scope || '。' FROM facts WHERE facts.rid=notes.rowid)
      WHEN 1 THEN (SELECT 'translated business text' || note_topic || '，useboundaryfor' || note_scope || '。' FROM facts WHERE facts.rid=notes.rowid)
      WHEN 2 THEN (SELECT note_scope || '；bodytranslated business text' || note_topic || '。' FROM facts WHERE facts.rid=notes.rowid)
      WHEN 3 THEN (SELECT 'translated business textcandidate：' || note_topic || '。' || note_scope || '。' FROM facts WHERE facts.rid=notes.rowid)
      WHEN 4 THEN (SELECT note_topic || 'andoral examtranslated business texthastranslated business text；' || note_scope || '。' FROM facts WHERE facts.rid=notes.rowid)
      WHEN 5 THEN (SELECT 'thistranslated business textsynthetictranslated business textareatranslated business textrecord' || note_topic || '，translated business text' || note_scope || '。' FROM facts WHERE facts.rid=notes.rowid)
      ELSE (SELECT 'translated business textfor' || note_topic || '。translated business textbeforetranslated business text：' || note_scope || '。' FROM facts WHERE facts.rid=notes.rowid)
    END,
    tags=json_array('translated business textoral exam',(SELECT note_topic FROM facts WHERE facts.rid=notes.rowid),(SELECT note_scope FROM facts WHERE facts.rid=notes.rowid)),
    note_id=replace(note_id,'NOTE_INTERP_DISTRACTOR_','NOTE_INTERP_COMMUNITY_')
WHERE note_id LIKE 'NOTE_INTERP_DISTRACTOR_%';
UPDATE comments
SET note_id=replace(note_id,'NOTE_INTERP_DISTRACTOR_','NOTE_INTERP_COMMUNITY_'),
    body=CASE rowid % 17
      WHEN 0 THEN 'translated business textpublic sample questionstranslated business textthistranslated business text，translated business textsegmenttranslated business textretrospective。' WHEN 1 THEN 'equipmenttranslated business texthastranslated business text，translated business textpurchasebeforestilltranslated business textofficialtranslated business textrequirement。'
      WHEN 2 THEN 'thistranslated business textrouteattranslated business textmaytranslated business text，suggestionretaintranslated business textbuffer。' WHEN 3 THEN 'refund/changerulestranslated business textchange，translated business textatticketingbeforetranslated business textquery。'
      WHEN 4 THEN 'personaltranslated business textandofficialnoticetranslated business textrecord。' WHEN 5 THEN 'clienttranslated business textpublicpractice materials。'
      WHEN 6 THEN 'translated business textwiredheadset，translated business textfortranslated business textstatustranslated business textverify。' WHEN 7 THEN 'hotelrefundabletranslated business texttotranslated business text。'
      WHEN 8 THEN 'thistranslated business textpracticearrangementifvoicetranslated business text。' WHEN 9 THEN 'translated business textlistening discriminationtranslated business textaccording tofirsttranslated business text，translated business text。'
      WHEN 10 THEN 'Nanjing Southstationtoexam sitealsotranslated business textmetroandtaxi。' WHEN 11 THEN 'pleasetranslated business textsourcepublishdate，translated business textrulestranslated business textbeforerules。'
      WHEN 12 THEN 'thistranslated business textordertranslated business texthastranslated business textitemattachment，translated business text。' WHEN 13 THEN 'translated business textusetranslated business textpredicted questionsorguaranteed passoftranslated business text。'
      WHEN 14 THEN 'publictranslated business textseattranslated business textaccording totranslated business text，translated business textcannottranslated business texthandbook。' WHEN 15 THEN 'suggestiontranslated business textnot yettranslated business textpurchaseandbookingtranslated business textdo notrecord，translated business textauthorization。'
      ELSE 'translated business text，executebeforestill needstranslated business textquery。' END
WHERE comment_id LIKE 'comment_interp_%';
PRAGMA foreign_keys=ON;

UPDATE comments
SET body=body || ' thistranslated business text《' || (SELECT title FROM notes WHERE notes.note_id=comments.note_id) || '》，translated business textretaintranslated business textoftranslated business textboundary。'
WHERE comment_id LIKE 'comment_interp_%';

-- Community posts/comments are historical catalog data. Stage-specific new
-- material is supplied by the release chain, so publication times must not
-- place a post in the future of event-000.
UPDATE notes
SET published_at = '2026-08-01T08:00:00+08:00'
WHERE published_at > '2026-08-01T09:00:00+08:00';

UPDATE comments
SET created_at = '2026-08-01T08:00:00+08:00'
WHERE created_at > '2026-08-01T09:00:00+08:00';
